package com.avizero.avidrive.api;
import com.avizero.avidrive.domain.Link; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import java.security.SecureRandom; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/links") public class LinkController { private final LinkRepository links; private final StoredFileRepository files; private final FolderRepository folders; private final PasswordEncoder encoder; private final SecureRandom random=new SecureRandom(); public LinkController(LinkRepository l,StoredFileRepository f,FolderRepository d,PasswordEncoder e){links=l;files=f;folders=d;encoder=e;}
 @PostMapping public ResponseEntity<?> create(@RequestBody LinkRequest r,Authentication a){Long owner=owner(a);if((r.file_id()==null)==(r.folder_id()==null))return bad(400,"РЈРєР°Р¶РёС‚Рµ file_id РёР»Рё folder_id");if(r.file_id()!=null&&!files.findById(r.file_id()).filter(x->x.ownerId.equals(owner)).isPresent())return bad(404,"Р¤Р°Р№Р» РЅРµ РЅР°Р№РґРµРЅ");if(r.folder_id()!=null&&!folders.findById(r.folder_id()).filter(x->x.ownerId.equals(owner)).isPresent())return bad(404,"РџР°РїРєР° РЅРµ РЅР°Р№РґРµРЅР°");Link l=new Link();l.token=token();l.ownerId=owner;l.fileId=r.file_id();l.folderId=r.folder_id();l.expiresAt=r.expires_at();l.passwordHash=r.password()==null||r.password().isBlank()?null:encoder.encode(r.password());l.canView=r.can_view();l.canDownload=r.can_download();l.canUpload=r.can_upload();l.canDelete=r.can_delete();l.canRename=r.can_rename();l.maxFileSizeMb=r.max_file_size_mb();l.maxTotalSizeMb=r.max_total_size_mb();links.save(l);return ResponseEntity.ok(Map.of("token",l.token,"url","/s/"+l.token));}
 @GetMapping public List<LinkView> list(@RequestParam String object_type,@RequestParam Long object_id,Authentication a){return links.findAll().stream().filter(l->l.ownerId.equals(owner(a))&&(("file".equals(object_type)&&object_id.equals(l.fileId))||("folder".equals(object_type)&&object_id.equals(l.folderId)))).map(LinkView::of).toList();}
 @PatchMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody LinkRequest r,Authentication a){Link l=links.findById(id).filter(x->x.ownerId.equals(owner(a))).orElse(null);if(l==null)return bad(404,"РЎСЃС‹Р»РєР° РЅРµ РЅР°Р№РґРµРЅР°");if(r.expires_at()!=null)l.expiresAt=r.expires_at();if(r.can_view_value()!=null)l.canView=r.can_view();if(r.can_download_value()!=null)l.canDownload=r.can_download();if(r.can_upload_value()!=null)l.canUpload=r.can_upload();if(r.can_delete_value()!=null)l.canDelete=r.can_delete();if(r.can_rename_value()!=null)l.canRename=r.can_rename();links.save(l);return ResponseEntity.ok(LinkView.of(l));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id,Authentication a){Link l=links.findById(id).filter(x->x.ownerId.equals(owner(a))).orElse(null);if(l==null)return bad(404,"РЎСЃС‹Р»РєР° РЅРµ РЅР°Р№РґРµРЅР°");links.delete(l);return ResponseEntity.noContent().build();} private Long owner(Authentication a){return ((AuthUser)a.getPrincipal()).id();}private String token(){byte[] b=new byte[24];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b).substring(0,32);}private ResponseEntity<Map<String,String>> bad(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));} public record LinkRequest(Long file_id,Long folder_id,String expires_at,String password,Boolean can_view_value,Boolean can_download_value,Boolean can_upload_value,Boolean can_delete_value,Boolean can_rename_value,Long max_file_size_mb,Long max_total_size_mb){public boolean can_view(){return can_view_value==null||can_view_value;} public boolean can_download(){return can_download_value!=null&&can_download_value;} public boolean can_upload(){return can_upload_value!=null&&can_upload_value;} public boolean can_delete(){return can_delete_value!=null&&can_delete_value;} public boolean can_rename(){return can_rename_value!=null&&can_rename_value;}} public record LinkView(Long id,String token,boolean can_view,boolean can_download,boolean can_upload,long view_count,long download_count){static LinkView of(Link l){return new LinkView(l.id,l.token,l.canView,l.canDownload,l.canUpload,l.viewCount,l.downloadCount);}}
}
